'use client'

import { useMemo, useState } from 'react'
import Link from 'next/link'
import { ArrowLeft, CirclePlus, Eye, Search, SquarePen, Trash, UserX } from 'lucide-react'
import toast from 'react-hot-toast'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import PageHeader from '@/components/ui/PageHeader'
import Badge from '@/components/ui/Badge'
import Pagination from '@/components/ui/Pagination'
import { ConfirmModal } from '@/components/ui/Modal'
import DataTable from '@/components/ui/DataTable'
import { DEPARTEMEN_LIST, formatDate } from '@/lib/utils'
import KaryawanModal from '@/components/karyawan/KaryawanModal'

const getInitialSearch = () => {
  if (typeof window === 'undefined') return ''
  return new URLSearchParams(window.location.search).get('search') || ''
}

export default function KaryawanNonactivePage() {
  const queryClient = useQueryClient()
  const [page, setPage] = useState(1)
  const [search, setSearch] = useState(getInitialSearch)
  const [statusFilter, setStatusFilter] = useState('')
  const [deptFilter, setDeptFilter] = useState('')
  const [showModal, setShowModal] = useState(false)
  const [editData, setEditData] = useState(null)
  const [deleteId, setDeleteId] = useState(null)
  const [pageSize, setPageSize] = useState(10)

  const params = new URLSearchParams({
    page,
    limit: pageSize,
    statusAktif: 'false',
    ...(search && { search }),
    ...(statusFilter && { status: statusFilter }),
    ...(deptFilter && { departemen: deptFilter }),
  })

  const { data: result, isLoading } = useQuery({
    queryKey: ['karyawan-nonactive', page, pageSize, search, statusFilter, deptFilter],
    queryFn: () => fetch(`/api/karyawan?${params}`).then((r) => r.json()),
    keepPreviousData: true,
  })

  const deleteMutation = useMutation({
    mutationFn: (id) => fetch(`/api/karyawan/${id}`, { method: 'DELETE' }).then((r) => r.json()),
    onSuccess: () => {
      toast.success('Karyawan berhasil dihapus')
      queryClient.invalidateQueries({ queryKey: ['karyawan-nonactive'] })
      queryClient.invalidateQueries({ queryKey: ['karyawan'] })
      queryClient.invalidateQueries({ queryKey: ['dashboard'] })
      setDeleteId(null)
    },
    onError: () => toast.error('Gagal menghapus karyawan'),
  })

  const rows = result?.data || []
  const total = result?.total || 0
  const totalPages = result?.totalPages || 1

  const columns = useMemo(() => [
    {
      accessorKey: 'nik',
      header: 'NIK',
      cell: ({ getValue }) => <span className="font-mono text-xs text-gray-600">{getValue()}</span>,
    },
    {
      accessorKey: 'nama',
      header: 'Nama',
      enableSorting: true,
      cell: ({ row }) => (
        <div>
          <div className="font-semibold text-gray-900">{row.original.nama}</div>
          <div className="text-xs text-gray-400 mt-0.5">{row.original.email || row.original.telepon || '-'}</div>
        </div>
      ),
    },
    {
      accessorKey: 'jabatan',
      header: 'Jabatan',
      cell: ({ getValue }) => getValue() || '-',
    },
    {
      accessorKey: 'departemen',
      header: 'Departemen',
      cell: ({ getValue }) => getValue() || '-',
    },
    {
      accessorKey: 'statusKontrak',
      header: 'Kontrak',
      cell: ({ getValue }) => <Badge status={getValue()} />,
    },
    {
      id: 'statusAktif',
      header: 'Status Aktif',
      cell: () => <Badge status="TIDAK_AKTIF" label="Nonaktif" />,
    },
    {
      accessorKey: 'tanggalMasuk',
      header: 'Tgl Masuk',
      cell: ({ getValue }) => formatDate(getValue(), 'dd/MM/yyyy'),
    },
    {
      id: 'aksi',
      header: 'Aksi',
      enableSorting: false,
      cell: ({ row }) => (
        <div className="flex items-center gap-1">
          <Link
            href={`/karyawan/${row.original._id || row.original.id}`}
            className="p-1.5 rounded-lg hover:bg-blue-50 text-blue-600 transition-colors"
            title="Detail"
          >
            <Eye className="w-4 h-4" />
          </Link>
          <button
            onClick={() => { setEditData(row.original); setShowModal(true) }}
            className="p-1.5 rounded-lg hover:bg-emerald-50 text-emerald-600 transition-colors"
            title="Edit / Aktifkan"
          >
            <SquarePen className="w-4 h-4" />
          </button>
          <button
            onClick={() => setDeleteId(row.original._id || row.original.id)}
            className="p-1.5 rounded-lg hover:bg-red-50 text-red-500 transition-colors"
            title="Hapus"
          >
            <Trash className="w-4 h-4" />
          </button>
        </div>
      ),
    },
  ], [])

  return (
    <div>
      <PageHeader
        title="Karyawan Nonaktif"
        subtitle={`Total ${total} karyawan nonaktif`}
        breadcrumb={[{ label: 'Dashboard', href: '/' }, { label: 'Karyawan', href: '/karyawan' }, { label: 'Nonaktif' }]}
        actions={
          <>
            <Link href="/karyawan" className="btn-secondary">
              <ArrowLeft className="w-4 h-4" /> Data Karyawan
            </Link>
            <button onClick={() => { setEditData(null); setShowModal(true) }} className="btn-primary">
              <CirclePlus className="w-4 h-4" /> Tambah Karyawan
            </button>
          </>
        }
      />

      <div className="card p-4 mb-4">
        <div className="flex items-start gap-3 rounded-xl border border-amber-100 bg-amber-50 px-4 py-3 mb-4">
          <UserX className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-semibold text-amber-800">Daftar karyawan nonaktif</p>
            <p className="text-xs text-amber-700 mt-0.5">Edit data karyawan lalu centang “Karyawan Aktif” untuk mengaktifkan kembali.</p>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Cari nama, NIK, jabatan..."
              className="form-input pl-9"
              value={search}
              onChange={(e) => { setSearch(e.target.value); setPage(1) }}
            />
          </div>
          <select className="form-select w-full sm:w-40" value={statusFilter}
            onChange={(e) => { setStatusFilter(e.target.value); setPage(1) }}>
            <option value="">Semua Kontrak</option>
            <option value="PKWTT">PKWTT</option>
            <option value="PKWT">PKWT</option>
            <option value="PROBATION">Probation</option>
          </select>
          <select className="form-select w-full sm:w-48" value={deptFilter}
            onChange={(e) => { setDeptFilter(e.target.value); setPage(1) }}>
            <option value="">Semua Departemen</option>
            {DEPARTEMEN_LIST.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
      </div>

      <div className="page-section">
        <DataTable
          data={rows}
          columns={columns}
          isLoading={isLoading}
          emptyMessage="Belum ada karyawan nonaktif"
          showPagination={false}
        />
        {!isLoading && rows.length > 0 && (
          <div className="px-4 py-3 border-t border-gray-100 flex flex-col sm:flex-row items-center justify-between gap-2">
            <p className="text-xs text-gray-500">
              Menampilkan {(page - 1) * pageSize + 1}-{Math.min(page * pageSize, total)} dari {total} data
            </p>
            <Pagination page={page} totalPages={totalPages} onPageChange={setPage} pageSize={pageSize} onPageSizeChange={(size) => { setPageSize(size); setPage(1) }} />
          </div>
        )}
      </div>

      <KaryawanModal
        isOpen={showModal}
        onClose={() => { setShowModal(false); setEditData(null) }}
        onSaved={() => {
          setShowModal(false)
          setEditData(null)
          queryClient.invalidateQueries({ queryKey: ['karyawan-nonactive'] })
          queryClient.invalidateQueries({ queryKey: ['karyawan'] })
          queryClient.invalidateQueries({ queryKey: ['dashboard'] })
        }}
        editData={editData}
      />

      <ConfirmModal
        isOpen={!!deleteId}
        onClose={() => setDeleteId(null)}
        onConfirm={() => deleteMutation.mutate(deleteId)}
        loading={deleteMutation.isPending}
        title="Hapus Karyawan"
        message="Apakah Anda yakin ingin menghapus data karyawan ini? Tindakan ini tidak dapat dibatalkan."
      />
    </div>
  )
}
